const item = $input.first().json;

// Assign team
let assigned_to = "";

switch (item.department) {
  case "Finance":
    assigned_to = "Finance Team";
    break;

  case "Technical":
    assigned_to = "Technical Support";
    break;

  case "Customer Success":
    assigned_to = "Customer Support";
    break;

  case "Sales":
    assigned_to = "Sales Team";
    break;

  default:
    assigned_to = "General Support";
}

// Assign SLA
let sla = "";

switch (item.priority) {
  case "High":
    sla = "2 Hours";
    break;

  case "Medium":
    sla = "8 Hours";
    break;

  default:
    sla = "24 Hours";
}

return [
  {
    json: {
      ...item,
      assigned_to,
      sla
    }
  }
];
